with RecursiveTagHierarchy as (
    select t.Id, t.TagName, array[t.Id] as AncestorIds, 1 as Level
    from Tags t
    where array_lower(array[t.Id],1) = 1
    union all
    select t.Id, t.TagName, r.AncestorIds || t.Id, r.Level + 1
    from Tags t
    join RecursiveTagHierarchy r on t.Id = r.Id + 1 and not t.Id = any (r.AncestorIds)
    where r.Level < 5
